-- Disposable synthetic database: column types and core FK/RLS shapes derived
-- from the production catalog. NOT a full production schema or patient dump.
CREATE ROLE postgres LOGIN CREATEROLE BYPASSRLS NOSUPERUSER NOCREATEDB;
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE service_role NOLOGIN BYPASSRLS;
GRANT anon,authenticated,service_role TO postgres WITH ADMIN OPTION;
GRANT CREATE ON DATABASE postgres TO postgres;
GRANT USAGE,CREATE ON SCHEMA public TO postgres;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT USAGE ON SCHEMA auth TO postgres,anon,authenticated,service_role;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
INSERT INTO auth.users VALUES('00000000-0000-4000-8000-000000000001'),('00000000-0000-4000-8000-000000000009');
GRANT REFERENCES ON auth.users TO postgres;
SET ROLE postgres;
CREATE TABLE public.persons(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,name text NOT NULL,email text,phone text,avatar_url text,color text DEFAULT '#60A5FA',is_default boolean DEFAULT false,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.medicos(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,nome text NOT NULL,especialidade text,crm text,telefone text,email text,observacoes text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),categoria_profissional text,conselho_tipo text,conselho_numero text,conselho_uf text,a1_identity_revision bigint NOT NULL DEFAULT 0);
CREATE TABLE public.farmacias(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,nome text NOT NULL,endereco text,telefone text,observacoes text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),tipo text,is_sus boolean NOT NULL DEFAULT false);
CREATE TABLE public.hospitais(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,nome text NOT NULL,endereco text,telefone text,tipo text,observacoes text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),medico_ids uuid[]);
CREATE TABLE public.locais(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,nome text NOT NULL,endereco text,telefone text,tipo text,observacoes text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),medico_ids text[]);
CREATE TABLE public.documents(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,person_id uuid REFERENCES persons ON DELETE CASCADE,category_id text,type text,title text NOT NULL,description text,metadata jsonb DEFAULT '{}',attachments jsonb DEFAULT '[]',is_favorite boolean DEFAULT false,vault_id uuid,hospital_id uuid REFERENCES hospitais ON DELETE SET NULL,medico_id uuid REFERENCES medicos ON DELETE SET NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),entidade_tipo text,entidade_id text);
CREATE TABLE public.tratamentos(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,person_id uuid REFERENCES persons ON DELETE CASCADE,nome text NOT NULL,status text NOT NULL DEFAULT 'ativo',cor text DEFAULT '#8B5CF6',observacoes text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),cid_ids text[],hospital_ids text[],local_ids text[],medico_ids text[],data_inicio date,condicao text,visual_icon text,visual_icon_revision integer NOT NULL DEFAULT 0,visual_icon_updated_at timestamptz,visual_icon_operation_id uuid);
CREATE TABLE public.cids(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,person_id uuid REFERENCES persons ON DELETE CASCADE,codigo text NOT NULL,descricao text NOT NULL,data_diagnostico date,medico_id uuid REFERENCES medicos ON DELETE SET NULL,hospital_id uuid REFERENCES hospitais ON DELETE SET NULL,local_id uuid REFERENCES locais ON DELETE SET NULL,observacoes text,anexo_url text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.medicamentos(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,person_id uuid REFERENCES persons ON DELETE CASCADE,document_id uuid REFERENCES documents ON DELETE SET NULL,medico_id uuid REFERENCES medicos ON DELETE SET NULL,farmacia_id uuid REFERENCES farmacias ON DELETE SET NULL,hospital_id uuid REFERENCES hospitais ON DELETE SET NULL,local_id uuid REFERENCES locais ON DELETE SET NULL,nome text NOT NULL,dosagem text NOT NULL,medico text,farmacia text,data_receita date,proxima_renovacao date,tipo_receita text DEFAULT 'comum',tipo_uso text DEFAULT 'continuo',forma_farmaceutica text,cor_principal text,cor_secundaria text,status text DEFAULT 'ativo',estoque_quantidade numeric DEFAULT 0,estoque_data_referencia date,estoque_horarios text[],estoque_unidade_por_dose numeric,estoque_unidade_medida text,estoque_ml_total numeric,estoque_gotas_por_ml numeric,formato text,cores text[],preco numeric,motivo_descontinuacao text,medico_descontinuacao_id uuid REFERENCES medicos ON DELETE SET NULL,medico_descontinuacao_nome text,substituido_por_id uuid REFERENCES medicamentos ON DELETE SET NULL,data_descontinuacao date,historico_dosagens jsonb DEFAULT '[]',observacoes text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),cid_ids text[],tratamento_ids text[],tipo_aquisicao text,data_retorno_sus date,lembrete_receita_modo text NOT NULL DEFAULT 'automatico',lembrete_receita_data date,catalog_snapshot jsonb,contexto_clinico_m1 jsonb);
CREATE TABLE public.dose_logs(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,person_id uuid REFERENCES persons ON DELETE CASCADE,medicamento_id uuid REFERENCES medicamentos ON DELETE CASCADE,data date NOT NULL,horario text NOT NULL,tomado_em timestamptz,ignorado_em timestamptz,quantidade numeric,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),observacoes text,synced boolean,dose_kind text CHECK(dose_kind IS NULL OR dose_kind IN ('scheduled','sos','extra','planned')),motivo text);
CREATE TABLE public.renovacoes(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,person_id uuid REFERENCES persons ON DELETE CASCADE,document_id uuid REFERENCES documents ON DELETE SET NULL,medicamento_id uuid REFERENCES medicamentos ON DELETE CASCADE,medico_id uuid REFERENCES medicos ON DELETE SET NULL,farmacia_id uuid REFERENCES farmacias ON DELETE SET NULL,hospital_id uuid REFERENCES hospitais ON DELETE SET NULL,local_id uuid REFERENCES locais ON DELETE SET NULL,quantidade numeric,preco numeric,lote text,validade_produto date,data date NOT NULL,anexo_url text,observacoes text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),tipo_aquisicao text,data_retorno_sus date,data_proxima_retirada date,exige_nova_receita boolean,data_aquisicao date,medicamento_nome text,medicamento_dosagem text,a3_location_snapshot jsonb,a3_location_changes jsonb NOT NULL DEFAULT '[]');
CREATE TABLE public.fornecimentos(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,person_id uuid NOT NULL REFERENCES persons ON DELETE CASCADE,titulo text NOT NULL,origem text NOT NULL,status text NOT NULL,farmacia_id uuid,medico_id uuid,local_id uuid,protocolo text,renovacao_meses integer,antecedencia_dias integer NOT NULL DEFAULT 30,receita_cada_retirada boolean NOT NULL DEFAULT false,observacoes text,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,uf text,indicacao text,catalogo_versao text);
CREATE TABLE public.fornecimento_ciclos(id uuid PRIMARY KEY,user_id uuid NOT NULL,person_id uuid NOT NULL,processo_id uuid NOT NULL REFERENCES fornecimentos ON DELETE CASCADE,status text NOT NULL,inicio date,fim date,protocolado_em timestamptz,autorizado_em timestamptz,observacoes text,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,uf_snapshot text,indicacao_snapshot text,origem_snapshot text,motivo text,preparar_ate date,consulta_id uuid,documentos_pessoais_conferidos boolean NOT NULL DEFAULT false,exigencia_local text,regra_versao text,UNIQUE(id,processo_id,user_id,person_id));
CREATE TABLE public.fornecimento_itens(id uuid PRIMARY KEY,user_id uuid NOT NULL,person_id uuid NOT NULL,processo_id uuid NOT NULL,ciclo_id uuid NOT NULL,medicamento_id uuid NOT NULL REFERENCES medicamentos ON DELETE CASCADE,dosagem text NOT NULL,quantidade_mensal numeric,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,catalogo_id text,UNIQUE(ciclo_id,medicamento_id,user_id,person_id));
CREATE TABLE public.retiradas(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,person_id uuid NOT NULL REFERENCES persons ON DELETE CASCADE,medicamento_id uuid NOT NULL REFERENCES medicamentos ON DELETE CASCADE,renovacao_origem_id uuid REFERENCES renovacoes ON DELETE SET NULL,renovacao_realizada_id uuid REFERENCES renovacoes ON DELETE SET NULL,medico_id uuid REFERENCES medicos ON DELETE SET NULL,farmacia_id uuid REFERENCES farmacias ON DELETE SET NULL,hospital_id uuid REFERENCES hospitais ON DELETE SET NULL,local_id uuid REFERENCES locais ON DELETE SET NULL,medicamento_nome text,medicamento_dosagem text,data date NOT NULL,horario time,tipo text NOT NULL DEFAULT 'sus' CHECK(tipo IN ('sus','farmacia','outro')),status text NOT NULL DEFAULT 'agendada' CHECK(status IN ('agendada','realizada','cancelada','nao_realizada')),quantidade_prevista numeric CHECK(quantidade_prevista>=0),quantidade_retirada numeric CHECK(quantidade_retirada>=0),exige_nova_receita boolean NOT NULL DEFAULT false,observacoes text,realizada_em timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),reagendamentos jsonb NOT NULL DEFAULT '[]',fornecimento_id uuid,fornecimento_ciclo_id uuid,a3_location_snapshot jsonb,a3_location_changes jsonb NOT NULL DEFAULT '[]',CHECK((fornecimento_id IS NULL)=(fornecimento_ciclo_id IS NULL)),FOREIGN KEY(fornecimento_ciclo_id,fornecimento_id,user_id,person_id) REFERENCES fornecimento_ciclos(id,processo_id,user_id,person_id),FOREIGN KEY(fornecimento_ciclo_id,medicamento_id,user_id,person_id) REFERENCES fornecimento_itens(ciclo_id,medicamento_id,user_id,person_id));
CREATE TABLE public.fornecimento_documentos(id uuid PRIMARY KEY,user_id uuid NOT NULL,person_id uuid NOT NULL,processo_id uuid NOT NULL,ciclo_id uuid NOT NULL,document_id uuid NOT NULL REFERENCES documents ON DELETE CASCADE,retirada_id uuid REFERENCES retiradas ON DELETE SET NULL,tipo text NOT NULL,estado text NOT NULL,entregue_em timestamptz,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE public.a1_treatment_phases(id uuid PRIMARY KEY,user_id uuid NOT NULL,person_id uuid NOT NULL,tratamento_id uuid NOT NULL REFERENCES tratamentos ON DELETE CASCADE,tipo text NOT NULL,data_efetiva date NOT NULL,origem text NOT NULL,profissional_id uuid,titulo text NOT NULL,observacoes text,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,deleted_at timestamptz,regime_a4 jsonb);
CREATE TABLE public.a1_prescription_links(id uuid PRIMARY KEY,user_id uuid NOT NULL,person_id uuid NOT NULL,medicamento_id uuid NOT NULL REFERENCES medicamentos ON DELETE CASCADE,renovacao_anterior_id uuid NOT NULL REFERENCES renovacoes ON DELETE CASCADE,renovacao_atual_id uuid NOT NULL REFERENCES renovacoes ON DELETE CASCADE,tipo text NOT NULL,origem text NOT NULL,observacoes text,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,deleted_at timestamptz);
CREATE TABLE public.a1_supply_locations(id uuid PRIMARY KEY,user_id uuid NOT NULL,person_id uuid NOT NULL,fornecimento_id uuid NOT NULL REFERENCES fornecimentos ON DELETE CASCADE,farmacia_id uuid,local_id uuid,inicio_vigencia date NOT NULL,origem text NOT NULL,observacoes text,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,deleted_at timestamptz,a3_location_snapshot jsonb);
CREATE TABLE public.medicamento_tratamentos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),medicamento_id uuid NOT NULL REFERENCES medicamentos ON DELETE CASCADE,tratamento_id uuid NOT NULL REFERENCES tratamentos ON DELETE CASCADE,UNIQUE(medicamento_id,tratamento_id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['dose_logs','medicamentos','renovacoes','retiradas','persons','documents','medicos','farmacias','hospitais','locais','tratamentos','cids','fornecimentos','fornecimento_ciclos','fornecimento_itens','fornecimento_documentos','a1_treatment_phases','a1_prescription_links','a1_supply_locations'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON public.%I TO authenticated,service_role',t);
 EXECUTE format('CREATE POLICY own ON public.%I FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid())',t);
 END LOOP; END $$;
ALTER TABLE public.medicamento_tratamentos ENABLE ROW LEVEL SECURITY;
CREATE POLICY own ON public.medicamento_tratamentos TO authenticated USING(EXISTS(SELECT 1 FROM public.medicamentos m WHERE m.id=medicamento_id AND m.user_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.medicamentos m WHERE m.id=medicamento_id AND m.user_id=auth.uid()));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.medicamento_tratamentos TO authenticated;
